svg.script:
/**/
(function() {
  // Elements
  var btnSup = document.getElementById('a12p9h-btn-sup');
  var btnMed = document.getElementById('a12p9h-btn-med');
  var btnInf = document.getElementById('a12p9h-btn-inf');

  var ringSupGrp = document.getElementById('a12p9h-ring-sup-group');
  var ringMedGrp = document.getElementById('a12p9h-ring-med-group');
  var ringInfGrp = document.getElementById('a12p9h-ring-inf-group');

  var ellipseSup = document.getElementById('a12p9h-ellipse-sup');
  var ellipseMed = document.getElementById('a12p9h-ellipse-med');
  var polyInf = document.getElementById('a12p9h-poly-inf');

  var cardSup = document.getElementById('a12p9h-card-sup');
  var cardMed = document.getElementById('a12p9h-card-med');
  var cardInf = document.getElementById('a12p9h-card-inf');

  var fetalSim = document.getElementById('a12p9h-fetal-head-simulator');
  var fetalCaliperText = document.getElementById('a12p9h-fetal-caliper-text');

  function setActiveRing(ring) {
    // Reset buttons
    btnSup.classList.remove('a12p9h-btn-active');
    btnMed.classList.remove('a12p9h-btn-active');
    btnInf.classList.remove('a12p9h-btn-active');

    // Reset ring paths
    ellipseSup.classList.remove('a12p9h-ring-active');
    ellipseMed.classList.remove('a12p9h-ring-active');
    polyInf.classList.remove('a12p9h-ring-active');

    // Reset cards
    cardSup.classList.remove('a12p9h-card-highlight');
    cardMed.classList.remove('a12p9h-card-highlight');
    cardInf.classList.remove('a12p9h-card-highlight');

    if (ring === 'sup') {
      btnSup.classList.add('a12p9h-btn-active');
      ellipseSup.classList.add('a12p9h-ring-active');
      cardSup.classList.add('a12p9h-card-highlight');
      fetalSim.setAttribute('transform', 'translate(335, 200)');
      if (fetalCaliperText) fetalCaliperText.textContent = 'Superior 13.0cm';
    } else if (ring === 'med') {
      btnMed.classList.add('a12p9h-btn-active');
      ellipseMed.classList.add('a12p9h-ring-active');
      cardMed.classList.add('a12p9h-card-highlight');
      fetalSim.setAttribute('transform', 'translate(335, 355)');
      if (fetalCaliperText) fetalCaliperText.textContent = 'GARGALO 10.5cm';
    } else if (ring === 'inf') {
      btnInf.classList.add('a12p9h-btn-active');
      polyInf.classList.add('a12p9h-ring-active');
      cardInf.classList.add('a12p9h-card-highlight');
      fetalSim.setAttribute('transform', 'translate(335, 490)');
      if (fetalCaliperText) fetalCaliperText.textContent = 'Inferior 11.0cm';
    }
  }

  // Event Listeners
  if (btnSup) btnSup.addEventListener('click', function() { setActiveRing('sup'); });
  if (btnMed) btnMed.addEventListener('click', function() { setActiveRing('med'); });
  if (btnInf) btnInf.addEventListener('click', function() { setActiveRing('inf'); });

  if (ringSupGrp) ringSupGrp.addEventListener('click', function() { setActiveRing('sup'); });
  if (ringMedGrp) ringMedGrp.addEventListener('click', function() { setActiveRing('med'); });
  if (ringInfGrp) ringInfGrp.addEventListener('click', function() { setActiveRing('inf'); });
})();
/**/
